-- Account profiles, community feed, comments, likes, and image fingerprints.
create table if not exists public.community_posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references auth.users(id) on delete cascade, author_name text not null check (char_length(author_name) between 1 and 60), body text not null check (char_length(btrim(body)) between 1 and 2000), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists community_posts_created_at_idx on public.community_posts(created_at desc);
create table if not exists public.post_comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.community_posts(id) on delete cascade, author_id uuid not null references auth.users(id) on delete cascade, author_name text not null check (char_length(author_name) between 1 and 60), body text not null check (char_length(btrim(body)) between 1 and 1000), created_at timestamptz not null default now());
create index if not exists post_comments_post_created_idx on public.post_comments(post_id, created_at);
create table if not exists public.post_likes (post_id uuid not null references public.community_posts(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (post_id, user_id));
alter table public.community_posts enable row level security; alter table public.post_comments enable row level security; alter table public.post_likes enable row level security;
drop policy if exists "Published community posts are public" on public.community_posts; create policy "Published community posts are public" on public.community_posts for select to anon, authenticated using (true);
drop policy if exists "Signed-in users create own posts" on public.community_posts; create policy "Signed-in users create own posts" on public.community_posts for insert to authenticated with check (author_id = (select auth.uid()));
drop policy if exists "Authors edit own posts" on public.community_posts; create policy "Authors edit own posts" on public.community_posts for update to authenticated using (author_id = (select auth.uid())) with check (author_id = (select auth.uid()));
drop policy if exists "Authors delete own posts" on public.community_posts; create policy "Authors delete own posts" on public.community_posts for delete to authenticated using (author_id = (select auth.uid()));
drop policy if exists "Comments on public posts are readable" on public.post_comments; create policy "Comments on public posts are readable" on public.post_comments for select to anon, authenticated using (exists (select 1 from public.community_posts p where p.id = post_id));
drop policy if exists "Signed-in users comment as themselves" on public.post_comments; create policy "Signed-in users comment as themselves" on public.post_comments for insert to authenticated with check (author_id = (select auth.uid()) and exists (select 1 from public.community_posts p where p.id = post_id));
drop policy if exists "Comment authors delete own comments" on public.post_comments; create policy "Comment authors delete own comments" on public.post_comments for delete to authenticated using (author_id = (select auth.uid()));
drop policy if exists "Like counts are public" on public.post_likes; drop policy if exists "Users read own likes" on public.post_likes; create policy "Users read own likes" on public.post_likes for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Users like as themselves" on public.post_likes; create policy "Users like as themselves" on public.post_likes for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "Users remove own likes" on public.post_likes; create policy "Users remove own likes" on public.post_likes for delete to authenticated using (user_id = (select auth.uid()));
grant select, insert, update, delete on public.community_posts to authenticated; grant select, insert, delete on public.post_comments to authenticated; grant select on public.community_posts, public.post_comments to anon; grant select, insert, delete on public.post_likes to authenticated;
create or replace function public.community_post_like_counts(post_ids uuid[]) returns table(post_id uuid, like_count bigint) language sql stable security definer set search_path = '' as $$ select p.id, count(l.user_id)::bigint from public.community_posts p left join public.post_likes l on l.post_id=p.id where p.id=any(post_ids) group by p.id; $$;
revoke all on function public.community_post_like_counts(uuid[]) from public; grant execute on function public.community_post_like_counts(uuid[]) to anon, authenticated;
drop policy if exists "No browser access by default" on public.profiles; drop policy if exists "Users read own profile" on public.profiles; create policy "Users read own profile" on public.profiles for select to authenticated using (id = (select auth.uid()));
drop policy if exists "Users update own profile" on public.profiles; create policy "Users update own profile" on public.profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid())); grant select, update (display_name) on public.profiles to authenticated;
create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles (id,email,display_name,role) values (new.id,new.email,coalesce(nullif(left(btrim(new.raw_user_meta_data ->> 'display_name'),60),''),left(coalesce(split_part(new.email,'@',1),'member'),60)),'user') on conflict (id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created_scamcheck on auth.users; create trigger on_auth_user_created_scamcheck after insert on auth.users for each row execute function public.handle_new_auth_user(); revoke all on function public.handle_new_auth_user() from public, anon, authenticated;
create or replace function public.set_community_author_name() returns trigger language plpgsql security definer set search_path = '' as $$ declare chosen_name text; begin select p.display_name into chosen_name from public.profiles p where p.id=new.author_id; if chosen_name is null or btrim(chosen_name)='' then select left(coalesce(nullif(split_part(u.email,'@',1),''),'Member'),60) into chosen_name from auth.users u where u.id=new.author_id; end if; new.author_name:=left(coalesce(nullif(btrim(chosen_name),''),'Member'),60); return new; end; $$;
drop trigger if exists set_community_post_author_name on public.community_posts; create trigger set_community_post_author_name before insert on public.community_posts for each row execute function public.set_community_author_name();
drop trigger if exists set_community_comment_author_name on public.post_comments; create trigger set_community_comment_author_name before insert on public.post_comments for each row execute function public.set_community_author_name(); revoke all on function public.set_community_author_name() from public, anon, authenticated;
create table if not exists public.image_signatures (id uuid primary key default gen_random_uuid(), image_hash text not null check (image_hash ~ '^[0-9a-f]{16}$'), label text not null check (char_length(btrim(label)) between 2 and 100), notes text not null default '' check (char_length(notes) <= 500), created_at timestamptz not null default now());
create index if not exists image_signatures_hash_idx on public.image_signatures(image_hash); alter table public.image_signatures enable row level security;
drop policy if exists "Community image signatures are searchable" on public.image_signatures; create policy "Community image signatures are searchable" on public.image_signatures for select to anon, authenticated using (true);
drop policy if exists "Signed-in users add image signatures" on public.image_signatures; create policy "Signed-in users add image signatures" on public.image_signatures for insert to authenticated with check (true);
revoke all on public.image_signatures from anon, authenticated; grant select (id,image_hash,label,notes,created_at) on public.image_signatures to anon, authenticated; grant insert (image_hash,label,notes) on public.image_signatures to authenticated;

-- Use a protected counter rather than exposing individual users who liked a post.
alter table public.community_posts add column if not exists like_count integer not null default 0 check (like_count >= 0);
update public.community_posts p set like_count=(select count(*)::integer from public.post_likes l where l.post_id=p.id);
create or replace function public.maintain_community_like_count() returns trigger language plpgsql security definer set search_path = '' as $$ begin if tg_op='INSERT' then update public.community_posts set like_count=like_count+1 where id=new.post_id; return new; elsif tg_op='DELETE' then update public.community_posts set like_count=greatest(0,like_count-1) where id=old.post_id; return old; end if; return null; end; $$;
drop trigger if exists maintain_like_count_insert on public.post_likes; create trigger maintain_like_count_insert after insert on public.post_likes for each row execute function public.maintain_community_like_count();
drop trigger if exists maintain_like_count_delete on public.post_likes; create trigger maintain_like_count_delete after delete on public.post_likes for each row execute function public.maintain_community_like_count();
revoke all on function public.maintain_community_like_count() from public, anon, authenticated;
revoke all on function public.community_post_like_counts(uuid[]) from public, anon, authenticated;
revoke update on public.community_posts from authenticated;
grant update (body) on public.community_posts to authenticated;
